import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

frobenius_kernel = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void frobenius_norm_kernel(const float* input, float* output, float* norm, int num_elements) {
    extern __shared__ float shared_data[];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    float temp = 0.0f;

    // Grid-stride loop for sum of squares
    while (idx < num_elements) {
        float val = input[idx];
        temp += val * val;
        idx += blockDim.x * gridDim.x;
    }

    shared_data[tid] = temp;
    __syncthreads();

    // Block reduction for sum
    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    // Atomic add to global sum
    if (tid == 0) {
        atomicAdd(norm, sqrtf(shared_data[0]));
    }

    // Reset idx for scaling
    idx = blockIdx.x * blockDim.x + tid;

    // Wait for norm calculation
    __syncthreads();
    float inv_norm = 1.0f / *norm;

    // Grid-stride scaling
    while (idx < num_elements) {
        output[idx] = input[idx] * inv_norm;
        idx += blockDim.x * gridDim.x;
    }
}

torch::Tensor frobenius_norm_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    float* norm;
    cudaMallocManaged(&norm, sizeof(float));
    *norm = 0.0f;

    int threads = 256;
    int blocks = (num_elements + threads - 1) / threads;
    blocks = blocks > 1024 ? 1024 : blocks;

    frobenius_norm_kernel<<<blocks, threads, threads * sizeof(float)>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        norm,
        num_elements
    );

    cudaFree(norm);
    return output;
}
"""

cpp_code = """
torch::Tensor frobenius_norm_cuda(torch::Tensor input);
"""

custom_ext = load_inline(
    name='custom_ext',
    cpp_sources=cpp_code,
    cuda_sources=frobenius_kernel,
    functions=['frobenius_norm_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.frobenius_op = custom_ext.frobenius_norm_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.frobenius_op(x)
